CREATE TABLE IF NOT EXISTS PackageTechnologyProfile(Id INTEGER PRIMARY KEY AUTOINCREMENT,PackageDefinitionId INTEGER NOT NULL,ProfileName TEXT NOT NULL,Revision INTEGER NOT NULL DEFAULT 1,IsDefault INTEGER NOT NULL DEFAULT 0,IsActive INTEGER NOT NULL DEFAULT 1,SourceType TEXT NOT NULL DEFAULT 'Internal',SourceName TEXT NOT NULL DEFAULT '',SourceReference TEXT NOT NULL DEFAULT '',CreatedAt TEXT NOT NULL,UpdatedAt TEXT NOT NULL,Notes TEXT NOT NULL DEFAULT '',FOREIGN KEY(PackageDefinitionId) REFERENCES PackageDefinition(Id));
CREATE UNIQUE INDEX IF NOT EXISTS IX_PackageTechnologyProfile_Default ON PackageTechnologyProfile(PackageDefinitionId) WHERE IsDefault=1;
CREATE TABLE IF NOT EXISTS PackageStencilRule(Id INTEGER PRIMARY KEY AUTOINCREMENT,TechnologyProfileId INTEGER NOT NULL UNIQUE,StencilThickness REAL NOT NULL DEFAULT 0,ApertureShape TEXT NOT NULL DEFAULT '',ReductionPercentX REAL NOT NULL DEFAULT 0,ReductionPercentY REAL NOT NULL DEFAULT 0,ReductionMmX REAL NOT NULL DEFAULT 0,ReductionMmY REAL NOT NULL DEFAULT 0,AreaRatioMin REAL NOT NULL DEFAULT 0,AspectRatioMin REAL NOT NULL DEFAULT 0,WindowPaneEnabled INTEGER NOT NULL DEFAULT 0,WindowRows INTEGER NOT NULL DEFAULT 0,WindowColumns INTEGER NOT NULL DEFAULT 0,WindowWeb REAL NOT NULL DEFAULT 0,HomePlateEnabled INTEGER NOT NULL DEFAULT 0,SnubnoseEnabled INTEGER NOT NULL DEFAULT 0,PasteCoveragePercent REAL NOT NULL DEFAULT 0,Rotation REAL NOT NULL DEFAULT 0,OffsetX REAL NOT NULL DEFAULT 0,OffsetY REAL NOT NULL DEFAULT 0,Notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS PackageAoiRule(Id INTEGER PRIMARY KEY AUTOINCREMENT,TechnologyProfileId INTEGER NOT NULL UNIQUE,MirtecClass TEXT NOT NULL DEFAULT '',InspectionMethod TEXT NOT NULL DEFAULT '',PolarityRequired INTEGER NOT NULL DEFAULT 0,Pin1Required INTEGER NOT NULL DEFAULT 0,BodyInspection INTEGER NOT NULL DEFAULT 0,LeadInspection INTEGER NOT NULL DEFAULT 0,SolderInspection INTEGER NOT NULL DEFAULT 0,MinLeadCount INTEGER NOT NULL DEFAULT 0,ExpectedPadCount INTEGER NOT NULL DEFAULT 0,LightingPreset TEXT NOT NULL DEFAULT '',ToleranceX REAL NOT NULL DEFAULT 0,ToleranceY REAL NOT NULL DEFAULT 0,ToleranceRotation REAL NOT NULL DEFAULT 0,Notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS PackagePlacementRule(Id INTEGER PRIMARY KEY AUTOINCREMENT,TechnologyProfileId INTEGER NOT NULL UNIQUE,YamahaRecognitionType TEXT NOT NULL DEFAULT '',NozzleName TEXT NOT NULL DEFAULT '',PickupHeight REAL NOT NULL DEFAULT 0,PlacementHeight REAL NOT NULL DEFAULT 0,VisionRequired INTEGER NOT NULL DEFAULT 0,PolarityRequired INTEGER NOT NULL DEFAULT 0,MaxRotationCorrection REAL NOT NULL DEFAULT 0,PickupOffsetX REAL NOT NULL DEFAULT 0,PickupOffsetY REAL NOT NULL DEFAULT 0,PlacementOffsetX REAL NOT NULL DEFAULT 0,PlacementOffsetY REAL NOT NULL DEFAULT 0,Notes TEXT NOT NULL DEFAULT '');
INSERT INTO PackageTechnologyProfile(PackageDefinitionId,ProfileName,Revision,IsDefault,IsActive,SourceType,SourceName,CreatedAt,UpdatedAt,Notes) SELECT Id,'Standard',1,1,1,'Internal','Existing Vega-SMD rule reference',datetime('now'),datetime('now'),'Values are linked to existing technology rules; equipment fields intentionally empty.' FROM PackageDefinition WHERE PackageName IN ('R0603','C0603','L0603','SOT23','SO08P127W078','QFN032P050W500','BGA064P080W800') AND NOT EXISTS(SELECT 1 FROM PackageTechnologyProfile t WHERE t.PackageDefinitionId=PackageDefinition.Id AND t.ProfileName='Standard' AND t.Revision=1);
INSERT INTO PackageStencilRule(TechnologyProfileId,ApertureShape,WindowPaneEnabled,Notes) SELECT t.Id,CASE p.PackageName WHEN 'QFN032P050W500' THEN 'WindowPane' WHEN 'BGA064P080W800' THEN 'Circle' ELSE 'Rectangle' END,CASE WHEN p.PackageName='QFN032P050W500' THEN 1 ELSE 0 END,'Adapter reference to existing Vega-SMD stencil strategy; no new numeric engineering values.' FROM PackageTechnologyProfile t JOIN PackageDefinition p ON p.Id=t.PackageDefinitionId WHERE NOT EXISTS(SELECT 1 FROM PackageStencilRule r WHERE r.TechnologyProfileId=t.Id);
